package rfcserver

import "encoding/hex"

// classicWorkAccept is a real logon-accept captured from A4H for a work logon in
// a CLASSIC-serializer session. Unlike the fast-ser templates, its whole
// capability body advertises classic serialization, so a client negotiates
// classic (sending 0x0201/0x0203 parameters our decoder reads) rather than
// fast-ser (0x5001). Per-session tokens (conversation id, RFC GUID) are patched
// at use. See docs/discoveries/0002-wire-constants.md.
var classicWorkAccept, _ = hex.DecodeString("")
